import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        String s = sc.next();
        StringBuilder sb = new StringBuilder(s);
        int removed = 0;

        // Iterate from 'z' down to 'b'
        for (char ch = 'z'; ch >= 'b'; ch--) {
            boolean changed;
            do {
                changed = false;
                for (int i = 0; i < sb.length(); i++) {
                    if (sb.charAt(i) == ch) {
                        boolean canRemove = false;
                        if (i > 0 && sb.charAt(i - 1) == ch - 1) {
                            canRemove = true;
                        }
                        if (i + 1 < sb.length() && sb.charAt(i + 1) == ch - 1) {
                            canRemove = true;
                        }
                        if (canRemove) {
                            sb.deleteCharAt(i);
                            removed++;
                            changed = true;
                            break; // restart scanning from beginning
                        }
                    }
                }
            } while (changed);
        }

        System.out.println(removed);
    }
}

